import{_ as a,o as t,c as o,a2 as d}from"./chunks/framework.Ch4PdLd_.js";const k=JSON.parse('{"title":"Todo 列表","description":"","frontmatter":{},"headers":[],"relativePath":"guide/todos.md","filePath":"guide/todos.md"}'),s={name:"guide/todos.md"};function i(n,e,l,p,r,c){return t(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="todo-列表" tabindex="-1">Todo 列表 <a class="header-anchor" href="#todo-列表" aria-label="Permalink to &quot;Todo 列表&quot;">​</a></h1><p>处理多步任务时，模型会用 <code>todo_write</code> 工具维护一个 Todo 列表。列表固定显示在输入框上方，让你随时知道它做到哪一步、接下来要做什么。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> ✓ 读取现有的配置加载逻辑</span></span>
<span class="line"><span> ▸ 新增 rateLimit 中间件</span></span>
<span class="line"><span> ○ 在 /login 路由上启用</span></span>
<span class="line"><span> ○ 补充测试</span></span>
<span class="line"><span>&gt;</span></span></code></pre></div><h2 id="什么时候会出现" tabindex="-1">什么时候会出现 <a class="header-anchor" href="#什么时候会出现" aria-label="Permalink to &quot;什么时候会出现&quot;">​</a></h2><p>模型被指示在这些情况下使用 Todo 列表：</p><ul><li>任务有三个左右或更多的独立步骤；</li><li>你一次给了一串任务；</li><li>你明确要求列出 todo。</li></ul><p>单步任务、简单修复、纯提问不会使用 Todo 列表。</p><p>Plan 模式的计划被批准后，计划里的 todos 会作为普通 todos 写入列表，第一项标为进行中，见 <a href="/nekcode/guide/plan-mode#review">Plan 模式</a>。</p><h2 id="每一项的状态" tabindex="-1">每一项的状态 <a class="header-anchor" href="#每一项的状态" aria-label="Permalink to &quot;每一项的状态&quot;">​</a></h2><table tabindex="0"><thead><tr><th>状态</th><th>含义</th></tr></thead><tbody><tr><td><code>pending</code></td><td>未开始</td></tr><tr><td><code>in_progress</code></td><td>进行中（模型被要求同一时间最多一项）</td></tr><tr><td><code>completed</code></td><td>已完成</td></tr><tr><td><code>cancelled</code></td><td>不再需要</td></tr></tbody></table><p>模型完成一项后会立刻标为 completed，不再需要的项标为 cancelled。</p><h2 id="模型如何更新列表" tabindex="-1">模型如何更新列表 <a class="header-anchor" href="#模型如何更新列表" aria-label="Permalink to &quot;模型如何更新列表&quot;">​</a></h2><p><code>todo_write</code> 有两种写法：</p><ul><li><code>merge: false</code>：用新列表<strong>整体替换</strong>旧列表；</li><li><code>merge: true</code>：按 <code>id</code> 更新已有项（只需传要改的字段），保持原有顺序，新的 <code>id</code> 追加到末尾。</li></ul><p>工具结果只返回一行摘要给模型，例如 <code>Todos updated: 2/5 completed. In progress: add-schema</code>。</p><h2 id="查看列表" tabindex="-1">查看列表 <a class="header-anchor" href="#查看列表" aria-label="Permalink to &quot;查看列表&quot;">​</a></h2><ul><li>输入框上方的小部件默认最多显示 8 行（<code>nek.yaml</code> 的 <code>todo.widgetMaxLines</code>）。</li><li><code>/todos</code> 显示当前分支的完整列表。</li></ul><p>Todo 列表保存在会话里，跟随<strong>当前分支</strong>：用 <code>/tree</code> 切换分支或 <code>/fork</code> 后，看到的是那条分支上的列表。</p><h2 id="收尾提醒" tabindex="-1">收尾提醒 <a class="header-anchor" href="#收尾提醒" aria-label="Permalink to &quot;收尾提醒&quot;">​</a></h2><p>一次运行结束时如果还有未完成（pending 或 in_progress）的 todos，nek 会提醒模型一次，让它继续把工作做完或更新列表状态。每次运行最多提醒一次，不会无限循环。</p><p>不需要这个行为时，在 <code>nek.yaml</code> 中关闭：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">todo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  settleReminder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  widgetMaxLines</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span></span></code></pre></div><p>见 <a href="/nekcode/reference/nek-yaml">nek.yaml</a>。</p><h2 id="子代理里的-todo" tabindex="-1">子代理里的 Todo <a class="header-anchor" href="#子代理里的-todo" aria-label="Permalink to &quot;子代理里的 Todo&quot;">​</a></h2><p>内置 <code>explorer</code> 只有只读工具，不提供 <code>todo_write</code>。自行定义的可写子代理若启用了该工具，Todo 列表属于子会话自己，不会显示在父会话的输入框上方。</p>`,25)])])}const u=a(s,[["render",i]]);export{k as __pageData,u as default};
